import json, math
def verify(answer):
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    req = {'team_pts_mae', 'abs_total_err', 'abs_margin_err', 'delta_luck_isolated', 'gradient_weight'}
    if not req.issubset(answer.keys()):
        return False
    t_mae = answer.get('team_pts_mae')
    tot_e = answer.get('abs_total_err')
    mar_e = answer.get('abs_margin_err')
    w_lr = answer.get('gradient_weight')
    if not all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in (t_mae, tot_e, mar_e, w_lr)):
        return False
    if float(t_mae) < 0.0 or float(tot_e) < 0.0 or float(mar_e) < 0.0:
        return False
    if answer.get('delta_luck_isolated') is True and float(w_lr) != 0.0:
        return False
    if answer.get('delta_luck_isolated') is False and not (0.0 < float(w_lr) <= 1.0):
        return False
    return math.isfinite(float(t_mae))

