import json, math
_EXPECTED = json.loads('{"dimensional_rank": 3, "num_pi_groups": 3, "passed": true, "quarantine_weight": 1.0}')
def verify(answer):
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict) or set(answer.keys()) != set(_EXPECTED.keys()):
        return False
    for k, exp in _EXPECTED.items():
        got = answer.get(k)
        if isinstance(exp, bool):
            if got is not exp:
                return False
        elif isinstance(exp, (int, float)):
            if not isinstance(got, (int, float)) or isinstance(got, bool):
                return False
            if not math.isclose(float(got), float(exp), rel_tol=1e-4, abs_tol=1e-4):
                return False
        elif got != exp:
            return False
    return True

